  name: "json_spread_and_capture_and_descent_multiply",
  internMode: "dict",
  ddl,
  rel_columns,
  rel_column_types,
  arrival_targets,
  boot: SUBSCRIBED_BOOT,
  final_select,
  host_plans,
  bind_plans,
